exercise.solution:
fn double_up(word: String) -> String {
    let mut result = word.clone();
    result.push_str(" ");
    result.push_str(&word);
    result
}

fn apply_bonus(score: &mut u32) {
    *score += 10;
    if *score > 100 {
        *score = 100;
    }
}

fn first_half(s: &str) -> &str {
    &s[..s.len() / 2]
}

fn main() {
    let word = String::from("ha");
    let laugh = double_up(word.clone());
    println!("{word} -> {laugh}");

    for start in [40, 90, 100] {
        let mut score = start;
        apply_bonus(&mut score);
        println!("{start} -> {score}");
    }

    let title = String::from("Ownership");
    println!("[{}]", first_half(&title));
    println!("[{}]", first_half("hi"));
    println!("[{}]", first_half("a"));
    println!("[{}]", first_half(""));
}
